// --- backend/admin-tools.web.js ---

import { Permissions, webMethod } from 'wix-web-module';
import { authentication } from 'wix-members-backend';
import wixData from 'wix-data';

// 🌟 The 'webMethod' wrapper ensures ONLY you (the Admin) can fire this code!
export const registerCustomerFromHQ = webMethod(Permissions.Admin, async (customerData) => {
    try {
        console.log(`📌 [BACKEND_ADMIN_TOOLS -> registerCustomerFromHQ]: Registering customer ${customerData?.email || "unknown"}`);

        // 1. Silently create the Member Account & PIN
        const registrationResult = await authentication.register(customerData.email, customerData.password, {
            contactInfo: {
                firstName: customerData.firstName,
                lastName: customerData.lastName,
                phones: [customerData.phone]
            }
        });

        const newUserId = registrationResult.member._id;

        // 🌟 2. Split the data into Contacts, Locations, and Profiles!
        const contactPayload = {
            userId: newUserId,
            firstName: customerData.firstName,
            lastName: customerData.lastName,
            phone: customerData.phone,
            email: customerData.email,
            isPrimary: true
        };

        const locationPayload = {
            userId: newUserId,
            address1: customerData.address1,
            address2: customerData.address2,
            city: customerData.city,
            state: customerData.state,
            zip: customerData.zip,
            isPrimary: true
        };

        const profilePayload = {
            _id: newUserId, 
            firstName: customerData.firstName, 
            lastName: customerData.lastName,
            phone: customerData.phone, 
            email: customerData.email, 
            address1: customerData.address1, 
            address2: customerData.address2,
            city: customerData.city, 
            state: customerData.state, 
            zip: customerData.zip,
            activeSubscription: false
        };

        // Save them all!
        await wixData.insert("customerContacts", contactPayload);
        await wixData.insert("customerProfiles", profilePayload);
        const savedAddress = await wixData.insert("customerLocations", locationPayload);

        console.log(`📌 [BACKEND_ADMIN_TOOLS -> registerCustomerFromHQ]: Success! Created userId=${newUserId}, addressId=${savedAddress._id}`);
        return { success: true, userId: newUserId, addressId: savedAddress._id };
        
    } catch (error) {
        console.error("📌 [BACKEND_ADMIN_TOOLS -> registerCustomerFromHQ]: Backend Registration Error:", error);
        return { success: false, message: error.message };
    }
});

// --- backend/aiBrain.web.js (Supabase Edge Function Connector) ---

import { Permissions, webMethod } from 'wix-web-module';
import { getSecret } from 'wix-secrets-backend';
import { fetch } from 'wix-fetch';
import wixData from 'wix-data';
import { sendTwilioSMS } from 'backend/twilioProxy';
import { sendMasterTransactionalEmail } from 'backend/emailDispatchEngine.jsw';

const EDGE_URL = 'https://lvynkeuceiqxafgpgdvs.supabase.co/functions/v1/ecmd-carbon-bridge';

async function callEdge(payload, includeBridgeKey = false) {
  const headers = { 'Content-Type': 'application/json' };
  if (includeBridgeKey) {
    const bridgeKey = (await getSecret('ECMD_BRIDGE_KEY')).trim();
    headers['x-bridge-key'] = bridgeKey;
    payload.bridgeKey = bridgeKey;
  }
  const res = await fetch(EDGE_URL, {
    method: 'POST',
    headers,
    body: JSON.stringify(payload)
  });
  return await res.json();
}

export const logTelemetryToSupabase = webMethod(Permissions.Anyone, (data = {}) =>
  callEdge({ action: 'telemetry', ...data })
);

export const searchBrain = webMethod(Permissions.Anyone, (query, options = {}) =>
  callEdge({ action: 'brain_search', query, ...options })
);

export const askEcmdBrain = webMethod(Permissions.Anyone, (question, vehicleContext = {}) =>
  callEdge({ action: 'ask_advisor', question, vehicleContext })
);

export const fetchSupabaseCrmBundle = webMethod(Permissions.Anyone, async (userId = '') => {
  try {
    return await callEdge({ action: 'get_crm_bundle', userId });
  } catch (e) {
    return { ok: false, vehicles: [], contacts: [], locations: [], jobs: [] };
  }
});

export const syncWixCrmToSupabase = webMethod(Permissions.Anyone, async () => {
  return await callEdge({ action: 'sync_crm_to_supabase' }, true);
});

export const pushCrmRecordToSupabase = webMethod(Permissions.Anyone, async (collection, item) => {
  try {
    return await callEdge({ action: 'crm_realtime_upsert', collection, item });
  } catch (e) {
    return { ok: false };
  }
});

export const getAiUnsureInbox = webMethod(Permissions.Anyone, async () => {
  return await callEdge({ action: 'get_ai_inbox' }, true);
});

export const answerAiInboxQuestion = webMethod(Permissions.Anyone, async (inboxId, ownerYesNoToggle = null, ownerAnswerText = '') => {
  return await callEdge({ action: 'answer_inbox_question', inboxId, ownerYesNoToggle, ownerAnswerText }, true);
});

export const smartConverseWithBrain = webMethod(Permissions.Anyone, async (payload = {}) => {
  const res = await callEdge({ action: 'smart_converse', ...payload });
  if (res && res.isUnsure) {
    const custLabel = `${payload.customerName || res.extractedCrm?.customerName || 'Visitor'} (${payload.customerPhone || res.extractedCrm?.customerPhone || 'No Phone'})`;
    const smsBody = `🤖 ECMD AI Unsure Alert!\nFrom: ${custLabel}\nQ: "${String(payload.message || '').slice(0, 110)}"\nToggle Yes/No in Console: ${res.yesNoQuestionForOwner || ''}`;
    try {
      await sendTwilioSMS('+18503777497', '+18503777497', smsBody);
    } catch (smsErr) {}
    try {
      await sendMasterTransactionalEmail('mlhammes1@gmail.com', {
        firstName: 'Michael',
        orderId: `AI-INBOX-${String(res.inboxItemId || '').slice(0, 8)}`,
        jobs: [{
          packageTitle: `AI Unsure Question from ${custLabel}`,
          vehicleInfo: res.extractedCrm?.vehicle || payload.vehicleContext || 'Customer Inquiry',
          specialInstructions: `QUESTION: ${payload.message}\n\nAI SUPPLEMENTAL REPLY SENT: ${res.reply}\n\nPROPOSED YES/NO RULE: ${res.yesNoQuestionForOwner}`
        }]
      }, 'UPDATE');
    } catch (emailErr) {}
  }
  return res;
});

export const classifyVehicleWithSupabase = webMethod(Permissions.Anyone, (vehicleInput) =>
  callEdge({ action: 'classify_vehicle', vehicleInput })
);

export const ingestToBrain = webMethod(Permissions.Admin, ({ category = 'general', title, content, metadata = {} }) =>
  callEdge({ action: 'brain_ingest', category, title, content, metadata }, true)
);

export const syncPackagesToBrain = webMethod(Permissions.Admin, async () => {
  const pkgRes = await wixData.query('servicePackages').limit(100).find({ suppressAuth: true });
  const results = [];
  for (const pkg of (pkgRes.items || [])) {
    const title = `${pkg.title || pkg.packageLevel || 'Package'} (${pkg.subCategory || 'All Vehicles'})`;
    const content = [
      `Package: ${pkg.title || ''}`,
      `Level: ${pkg.packageLevel || ''}`,
      `Detail Type: ${pkg.detailType || ''}`,
      `Vehicle Tier: ${pkg.subCategory || ''}`,
      `Price: $${pkg.price || 0} (Sale: $${pkg.salePrice || pkg.price || 0})`,
      `Duration: ${pkg.duration || ''} hrs`
    ].join('\n');
    const saved = await callEdge({
      action: 'brain_ingest',
      category: 'package',
      title,
      content,
      metadata: { wixId: pkg._id, price: pkg.price, subCategory: pkg.subCategory }
    }, true);
    results.push(saved);
  }
  return { syncedCount: results.length };
});

export const compilePageForMigration = webMethod(Permissions.Anyone, (pageSlug = '/home') =>
  callEdge({ action: 'compile_migration', pageSlug })
);

export const saveBlueprintToCms = webMethod(Permissions.Admin, async (route, content) => {
  return callEdge({
    action: 'brain_ingest',
    items: [{
      category: 'migration_blueprint',
      title: `FullBlueprint${route}`,
      content: content,
      metadata: { 
        route: route, 
        timestamp: Date.now() 
      }
    }]
  }, true);
});

export const remoteSpiderAllPages = webMethod(Permissions.Anyone, async () => {
  const baseUrl = 'https://www.ecmdutah.com';
  const paths = ['/', '/packages', '/booking-hq', '/detailer', '/checkout'];

  const results = await Promise.all(paths.map(async (path) => {
    const url = path === '/' ? baseUrl : `${baseUrl}${path}`;
    try {
      const res = await fetch(url);
      const html = await res.text();

      // Extract component IDs
      const idMatches = [...html.matchAll(/id="([^"]+)"/g)].map(m => m[1]);
      const uniqueIds = [...new Set(idMatches)];

      // Extract CSS classes
      const classMatches = [...html.matchAll(/class="([^"]+)"/g)].map(m => m[1]);
      const allClasses = classMatches.flatMap(c => c.split(/\s+/)).filter(Boolean);
      const uniqueClasses = [...new Set(allClasses)];

      // Extract SSR HTML structure (tags)
      const tagsMatches = [...html.matchAll(/<([a-zA-Z0-9\-]+)[^>]*>/g)].map(m => m[1]);
      const uniqueTags = [...new Set(tagsMatches)];

      const content = [
        `Page URL: ${url}`,
        `HTML Structure Tags: ${uniqueTags.join(', ')}`,
        `Component IDs: ${uniqueIds.join(', ')}`,
        `CSS Classes: ${uniqueClasses.join(', ')}`
      ].join('\n');

      // Ingest into Supabase ecmd_brain
      const saved = await callEdge({
        action: 'brain_ingest',
        items: [{
          category: 'migration_blueprint',
          title: `FullBlueprint${path}`,
          content: content,
          metadata: { 
            route: path, 
            timestamp: Date.now() 
          }
        }]
      }, true);

      return { path, status: 'success', saved };
    } catch (error) {
      return { path, status: 'error', error: error.message };
    }
  }));

  return results;
});

// --- backend/authBackend.jsw ---

import wixData from 'wix-data';

export async function verifyEmailInDB(userId) {
    try {
        console.log(`📌 [BACKEND_AUTH -> verifyEmailInDB]: Verifying email for userId=${userId}`);
        // suppressAuth: true allows this to run even if they aren't logged in on that device
        let res = await wixData.query("customerProfiles").eq("_id", userId).find({ suppressAuth: true });
        
        if (res.items.length > 0) {
            let profile = res.items[0];
            profile.emailConfirmed = true; // 💥 Flips your custom boolean
            await wixData.update("customerProfiles", profile, { suppressAuth: true });
            console.log(`📌 [BACKEND_AUTH -> verifyEmailInDB]: Successfully confirmed email for userId=${userId}`);
            return true;
        }
        console.warn(`📌 [BACKEND_AUTH -> verifyEmailInDB]: No customerProfiles record found for userId=${userId}`);
        return false;
    } catch (e) {
        console.error("📌 [BACKEND_AUTH -> verifyEmailInDB]: Verification failed", e);
        return false;
    }
}

// --- backend/braintreeEngine.jsw ---

import braintree from 'braintree';
import { getSecret } from 'wix-secrets-backend';

// Helper function to initialize the gateway securely
async function initBraintreeGateway() {
    const merchantId = await getSecret("BT_MERCHANT_ID");
    const publicKey = await getSecret("BT_PUBLIC_KEY");
    const privateKey = await getSecret("BT_PRIVATE_KEY");

    return new braintree.BraintreeGateway({
        environment: braintree.Environment.Sandbox,
        merchantId: merchantId,
        publicKey: publicKey,
        privateKey: privateKey
    });
}

export async function generateClientToken() {
    try {
        console.log("📌 [BACKEND_BRAINTREE -> generateClientToken]: Requesting Braintree client token...");
        const gateway = await initBraintreeGateway();
        const response = await gateway.clientToken.generate({});
        
        if (response.clientToken) {
            console.log("📌 [BACKEND_BRAINTREE -> generateClientToken]: Token generated successfully.");
            return { success: true, clientToken: response.clientToken };
        } else {
            console.warn("📌 [BACKEND_BRAINTREE -> generateClientToken]: No clientToken returned by Braintree.");
            return { success: false, error: "Failed to generate token from Braintree." };
        }
    } catch (error) {
        console.error("📌 [BACKEND_BRAINTREE -> generateClientToken]: Backend Braintree Error:", error);
        return { success: false, error: error.message };
    }
}

export async function processBraintreePayment(nonce, amount) {
    try {
        console.log(`📌 [BACKEND_BRAINTREE -> processBraintreePayment]: Processing sale for amount=$${amount}`);
        const gateway = await initBraintreeGateway();
        
        const result = await gateway.transaction.sale({
            amount: amount.toString(),
            paymentMethodNonce: nonce,
            options: {
                submitForSettlement: true // Instantly captures the funds
            }
        });

        if (result.success) {
            console.log(`📌 [BACKEND_BRAINTREE -> processBraintreePayment]: Success! transactionId=${result.transaction.id}`);
            return { success: true, transactionId: result.transaction.id };
        } else {
            console.warn(`📌 [BACKEND_BRAINTREE -> processBraintreePayment]: Declined/Failed: ${result.message}`);
            return { success: false, error: result.message };
        }
    } catch (error) {
        console.error("📌 [BACKEND_BRAINTREE -> processBraintreePayment]: Backend Braintree Charge Error:", error);
        return { success: false, error: error.message };
    }
}

// --- backend/calendar-dispatcher.web.js ---

import { getSecret } from 'wix-secrets-backend';
import { google } from 'googleapis';
import { Permissions, webMethod } from 'wix-web-module';
import realtimeBackend from 'wix-realtime-backend';
import wixData from 'wix-data'; 

// 🌟 YOUR MASTER DISPATCH CALENDAR ID:
const ADMIN_CALENDAR_ID = "c_7a27c584158dbb455686d19059303a63a1913ae7dcc0e6e022e178bf588a40a0@group.calendar.google.com"; 

// ==========================================
// 🔐 GOOGLE AUTHENTICATION ENGINE
// ==========================================
async function getGoogleAuth() {
    try {
        const secretString = await getSecret("GOOGLE_CALENDAR_KEY");
        const credentials = JSON.parse(secretString);

        const auth = new google.auth.JWT(
            credentials.client_email,
            null,
            credentials.private_key,
            ['https://www.googleapis.com/auth/calendar.events'] 
        );

        return auth;
    } catch (error) {
        console.error("📌 [BACKEND_CALENDAR_DISPATCHER -> getGoogleAuth]: 🚨 Error logging into Google:", error);
        throw new Error("Failed to authenticate with Google Calendar.");
    }
}

// ==========================================
// 🗓️ 1. SCHEDULE NEW JOB (Returns Event IDs)
// ==========================================
export const scheduleDetailingJob = webMethod(Permissions.Anyone, async (calendarId, appointmentDetails) => {
    try {
        console.log(`📌 [BACKEND_CALENDAR_DISPATCHER -> scheduleDetailingJob]: Initiating push to Google Calendar: ${calendarId}`);
        const authClient = await getGoogleAuth();
        const calendar = google.calendar({ version: 'v3', auth: authClient });

        const eventPayload = {
            summary: appointmentDetails.title,
            description: appointmentDetails.description,
            start: { dateTime: appointmentDetails.startTime, timeZone: 'America/Denver' },
            end: { dateTime: appointmentDetails.endTime, timeZone: 'America/Denver' },
        };

        // 1. PUSH TO THE DETAILER'S CALENDAR
        const cleanCalendarId = calendarId.trim();
        
        const response = await calendar.events.insert({
            calendarId: cleanCalendarId,
            requestBody: eventPayload
        });
        let detailerEventId = response.data.id;
        console.log(`📌 [BACKEND_CALENDAR_DISPATCHER -> scheduleDetailingJob]: Success! Detailer Event ID: ${detailerEventId}`);

        // 2. PUSH "CARBON COPY" TO THE ADMIN CALENDAR
        let adminEventId = null;
        if (ADMIN_CALENDAR_ID) {
            try {
                const adminPayload = { ...eventPayload, summary: `[${appointmentDetails.detailerName || "Assigned"}] ${appointmentDetails.title}` };
                const adminRes = await calendar.events.insert({
                    calendarId: ADMIN_CALENDAR_ID.trim(),
                    requestBody: adminPayload
                });
                adminEventId = adminRes.data.id;
                console.log(`📌 [BACKEND_CALENDAR_DISPATCHER -> scheduleDetailingJob]: Success! Admin Event ID: ${adminEventId}`);
            } catch (adminErr) {
                console.error("📌 [BACKEND_CALENDAR_DISPATCHER -> scheduleDetailingJob]: 🚨 Admin Copy Failed:", adminErr.message);
            }
        }

        return { success: true, eventId: detailerEventId, adminEventId: adminEventId };
        
    } catch (error) {
        console.error("📌 [BACKEND_CALENDAR_DISPATCHER -> scheduleDetailingJob]: 🚨 GOOGLE API CRASH:", error.message);
        
        try {
            await wixData.insert("syncErrors", {
                title: "Failed Google Calendar Sync",
                calendarId: calendarId,
                payload: JSON.stringify(appointmentDetails),
                errorMessage: error.message,
                timestamp: new Date()
            });
        } catch (dbErr) { console.error("📌 [BACKEND_CALENDAR_DISPATCHER -> syncErrorsInsert]: 🚨 FAILSAFE CRASH", dbErr); }

        return { success: false, error: error.message };
    }
});

// ==========================================
// 🔄 2. RESCHEDULE & SELF-HEALING ENGINE
// ==========================================
export const updateOrRestoreDetailingJob = webMethod(Permissions.Anyone, async (calendarId, savedEventIds, appointmentDetails) => {
    try {
        console.log(`📌 [BACKEND_CALENDAR_DISPATCHER -> updateOrRestoreDetailingJob]: Rescheduling job for: ${calendarId}`);
        const authClient = await getGoogleAuth();
        const calendar = google.calendar({ version: 'v3', auth: authClient });

        const eventPayload = {
            summary: appointmentDetails.title,
            description: appointmentDetails.description,
            start: { dateTime: appointmentDetails.startTime, timeZone: 'America/Denver' },
            end: { dateTime: appointmentDetails.endTime, timeZone: 'America/Denver' },
        };

        let activeDetailerId = savedEventIds?.eventId;
        let activeAdminId = savedEventIds?.adminEventId;

        // 1. UPDATE DETAILER CALENDAR (WITH SELF-HEALING)
        try {
            if (activeDetailerId) {
                await calendar.events.patch({ calendarId: calendarId, eventId: activeDetailerId, requestBody: eventPayload });
                console.log(`📌 [BACKEND_CALENDAR_DISPATCHER -> updateOrRestoreDetailingJob]: Updated existing Detailer event.`);
            } else { throw new Error("No ID"); }
        } catch (err) {
            console.warn("📌 [BACKEND_CALENDAR_DISPATCHER -> updateOrRestoreDetailingJob]: Detailer event missing or deleted! Recreating...");
            const res = await calendar.events.insert({ calendarId: calendarId, requestBody: eventPayload });
            activeDetailerId = res.data.id;
        }

        // 2. UPDATE ADMIN CALENDAR
        try {
            const adminPayload = { ...eventPayload, summary: `[${appointmentDetails.detailerName || "Assigned"}] ${appointmentDetails.title}` };
            if (activeAdminId) {
                await calendar.events.patch({ calendarId: ADMIN_CALENDAR_ID, eventId: activeAdminId, requestBody: adminPayload });
                console.log(`📌 [BACKEND_CALENDAR_DISPATCHER -> updateOrRestoreDetailingJob]: Updated existing Admin event.`);
            } else { throw new Error("No ID"); }
        } catch (err) {
            console.warn("📌 [BACKEND_CALENDAR_DISPATCHER -> updateOrRestoreDetailingJob]: Admin event missing! Recreating...");
            const adminPayload = { ...eventPayload, summary: `[${appointmentDetails.detailerName || "Assigned"}] ${appointmentDetails.title}` };
            const adminRes = await calendar.events.insert({ calendarId: ADMIN_CALENDAR_ID, requestBody: adminPayload });
            activeAdminId = adminRes.data.id;
        }

        return { success: true, eventId: activeDetailerId, adminEventId: activeAdminId };

    } catch (error) {
        console.error("📌 [BACKEND_CALENDAR_DISPATCHER -> updateOrRestoreDetailingJob]: 🚨 Reschedule Failed:", error.message);
        return { success: false, error: error.message };
    }
});

// ==========================================
// 📡 REALTIME NETWORK BROADCASTER
// ==========================================
export const broadcastCalendarUpdate = webMethod(Permissions.Anyone, async () => {
    try {
        await realtimeBackend.publish({ name: "CalendarSync" }, { message: "SlotBooked" });
        console.log("📌 [BACKEND_CALENDAR_DISPATCHER -> broadcastCalendarUpdate]: Broadcast successful.");
    } catch (err) {
        console.error("📌 [BACKEND_CALENDAR_DISPATCHER -> broadcastCalendarUpdate]: 🚨 Broadcast error:", err);
    }
});

// ==========================================
// 🗑️ DELETE GOOGLE EVENT (Triggered by CMS)
// ==========================================
export const deleteGoogleEvent = webMethod(Permissions.Anyone, async (calendarId, eventId, adminEventId) => {
    try {
        const authClient = await getGoogleAuth();
        const calendar = google.calendar({ version: 'v3', auth: authClient });

        // 1. Delete from Detailer Calendar
        if (calendarId && eventId) {
            try {
                await calendar.events.delete({ calendarId: calendarId, eventId: eventId });
                console.log(`📌 [BACKEND_CALENDAR_DISPATCHER -> deleteGoogleEvent]: Deleted event from Detailer Calendar.`);
            } catch (e) { console.warn("📌 [BACKEND_CALENDAR_DISPATCHER -> deleteGoogleEvent]: Detailer event already deleted or not found."); }
        }

        // 2. Delete from Admin Calendar
        if (ADMIN_CALENDAR_ID && adminEventId) {
            try {
                await calendar.events.delete({ calendarId: ADMIN_CALENDAR_ID, eventId: adminEventId });
                console.log(`📌 [BACKEND_CALENDAR_DISPATCHER -> deleteGoogleEvent]: Deleted event from Admin Calendar.`);
            } catch (e) { console.warn("📌 [BACKEND_CALENDAR_DISPATCHER -> deleteGoogleEvent]: Admin event already deleted or not found."); }
        }
        return true;
    } catch (error) {
        console.error("📌 [BACKEND_CALENDAR_DISPATCHER -> deleteGoogleEvent]: 🚨 Failed to delete events:", error.message);
        return false;
    }
});

// --- backend/calendarTasks.js ---

import wixData from 'wix-data';

export async function releaseAbandonedTimeSlots() {
    // ⏳ Set the time limit (15 minutes)
    const IDLE_MINUTES = 15;
    const cutoffTime = new Date();
    cutoffTime.setMinutes(cutoffTime.getMinutes() - IDLE_MINUTES);

    try {
        let queryResults = await wixData.query("temporaryData")
            .isNotEmpty("assignedSlotText")
            .lt("_updatedDate", cutoffTime)
            .find({ suppressAuth: true });

        if (queryResults.items.length > 0) {
            console.log(`📌 [BACKEND_CALENDAR_TASKS -> releaseAbandonedTimeSlots]: Found ${queryResults.items.length} abandoned slots. Releasing...`);
            
            let itemsToUpdate = queryResults.items.map(item => {
                item.assignedDate = null;
                item.assignedTime = null;
                item.assignedTimeToken = null;
                item.assignedDetailerId = null;
                item.assignedSlotText = null;
                return item;
            });

            await wixData.bulkUpdate("temporaryData", itemsToUpdate, { suppressAuth: true });
            console.log("📌 [BACKEND_CALENDAR_TASKS -> releaseAbandonedTimeSlots]: Abandoned slots successfully released.");
        } else {
            console.log("📌 [BACKEND_CALENDAR_TASKS -> releaseAbandonedTimeSlots]: No abandoned slots found.");
        }
    } catch (error) {
        console.error("📌 [BACKEND_CALENDAR_TASKS -> releaseAbandonedTimeSlots]: 🚨 Backend Cleanup Error:", error);
    }
}

// --- backend/data.js ---

import wixData from 'wix-data';
import { deleteGoogleEvent } from 'backend/calendar-dispatcher.web';
import { pushCrmRecordToSupabase } from 'backend/aiBrain.web';

// ==========================================
// 🌎 DYNAMIC US SERVICE ADDRESS TIMEZONE RESOLVER (0ms)
// ==========================================
export function resolveServiceTimezone(stateRaw = "", zipRaw = "") {
    let st = String(stateRaw || "").trim().toUpperCase();
    let zip = String(zipRaw || "").trim();
    let zip3 = zip.substring(0, 3);

    // 1. ZIP-prefix overrides for split states (Florida Panhandle, Texas El Paso, etc.)
    if (zip3 === "324" || zip3 === "325") return "America/Chicago"; // Pensacola / Panama City, FL (Central)
    if (zip.startsWith("32") || zip.startsWith("33") || zip.startsWith("34")) return "America/New_York"; // Rest of FL (Eastern)
    if (zip.startsWith("84")) return "America/Denver"; // Utah (Mountain)
    if (zip3 === "798" || zip3 === "799") return "America/Denver"; // El Paso, TX (Mountain)

    // 2. State-level lookup
    const stateMap = {
        // Mountain Time
        "UT": "America/Denver", "UTAH": "America/Denver",
        "CO": "America/Denver", "COLORADO": "America/Denver",
        "WY": "America/Denver", "WYOMING": "America/Denver",
        "MT": "America/Denver", "MONTANA": "America/Denver",
        "NM": "America/Denver", "NEW MEXICO": "America/Denver",
        "ID": "America/Denver", "IDAHO": "America/Denver",
        "AZ": "America/Phoenix", "ARIZONA": "America/Phoenix",

        // Central Time
        "AL": "America/Chicago", "ALABAMA": "America/Chicago",
        "MS": "America/Chicago", "MISSISSIPPI": "America/Chicago",
        "LA": "America/Chicago", "LOUISIANA": "America/Chicago",
        "TX": "America/Chicago", "TEXAS": "America/Chicago",
        "OK": "America/Chicago", "OKLAHOMA": "America/Chicago",
        "AR": "America/Chicago", "ARKANSAS": "America/Chicago",
        "TN": "America/Chicago", "TENNESSEE": "America/Chicago",
        "IL": "America/Chicago", "ILLINOIS": "America/Chicago",
        "MO": "America/Chicago", "MISSOURI": "America/Chicago",
        "WI": "America/Chicago", "WISCONSIN": "America/Chicago",
        "MN": "America/Chicago", "MINNESOTA": "America/Chicago",
        "IA": "America/Chicago", "IOWA": "America/Chicago",
        "KS": "America/Chicago", "KANSAS": "America/Chicago",
        "NE": "America/Chicago", "NEBRASKA": "America/Chicago",

        // Eastern Time
        "GA": "America/New_York", "GEORGIA": "America/New_York",
        "SC": "America/New_York", "SOUTH CAROLINA": "America/New_York",
        "NC": "America/New_York", "NORTH CAROLINA": "America/New_York",
        "VA": "America/New_York", "VIRGINIA": "America/New_York",
        "NY": "America/New_York", "NEW YORK": "America/New_York",
        "PA": "America/New_York", "PENNSYLVANIA": "America/New_York",
        "OH": "America/New_York", "OHIO": "America/New_York",
        "MI": "America/New_York", "MICHIGAN": "America/New_York",

        // Pacific Time
        "CA": "America/Los_Angeles", "CALIFORNIA": "America/Los_Angeles",
        "NV": "America/Los_Angeles", "NEVADA": "America/Los_Angeles",
        "OR": "America/Los_Angeles", "OREGON": "America/Los_Angeles",
        "WA": "America/Los_Angeles", "WASHINGTON": "America/Los_Angeles"
    };

    if (st === "FL" || st === "FLORIDA") return "America/Chicago";

    return stateMap[st] || "America/Chicago";
}

function extractCalendarYMD(rawDate, tz = "America/Chicago") {
    let d = new Date(rawDate);
    let utcHour = d.getUTCHours();
    if (utcHour <= 8 || utcHour === 12) {
        return {
            year: d.getUTCFullYear(),
            month: d.getUTCMonth(),
            day: d.getUTCDate()
        };
    }
    let parts = new Intl.DateTimeFormat('en-US', {
        timeZone: tz,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
    }).formatToParts(d);

    return {
        year: Number(parts.find(p => p.type === 'year').value),
        month: Number(parts.find(p => p.type === 'month').value) - 1,
        day: Number(parts.find(p => p.type === 'day').value)
    };
}

function normalizeCalendarDateToNoonUTC(rawDate, tz = "America/Chicago") {
    if (!rawDate) return null;
    let d = new Date(rawDate);
    if (isNaN(d.getTime())) return rawDate;

    let { year, month, day } = extractCalendarYMD(d, tz);
    return new Date(Date.UTC(year, month, day, 12, 0, 0, 0));
}

function buildLocalServiceTimestamp(rawServiceDate, targetHour24, tz = "America/Chicago") {
    if (!rawServiceDate) return null;
    let { year, month, day } = extractCalendarYMD(rawServiceDate, tz);

    let probeUTC = new Date(Date.UTC(year, month, day, 12, 0, 0, 0));
    let tzParts = new Intl.DateTimeFormat('en-US', {
        timeZone: tz,
        timeZoneName: 'shortOffset'
    }).formatToParts(probeUTC);

    let offsetStr = tzParts.find(p => p.type === 'timeZoneName')?.value || "GMT-5";
    let offsetHours = parseInt(offsetStr.replace("GMT", ""), 10);
    if (isNaN(offsetHours)) offsetHours = -5;

    return new Date(Date.UTC(year, month, day, targetHour24 - offsetHours, 0, 0, 0));
}

function normalizeTimeToken(timeToken, scheduledTime = "") {
    let t = String(timeToken || "").trim();
    let s = String(scheduledTime || "").toLowerCase();

    if (t === "token_1" || t === "slot_1" || t === "AM" || s.includes("9-11")) return "token_1";
    if (t === "token_2" || t === "slot_2" || t === "PM" || s.includes("1-3")) return "token_2";
    if (t === "token_3" || t === "slot_3" || t === "3rd" || s.includes("4-6")) return "token_3";
    return t || "token_1";
}

function normalizeDiscountsArray(discountsApplied, discountsTotal = 0) {
    if (!Array.isArray(discountsApplied) || discountsApplied.length === 0) return [];
    return discountsApplied.map(d => {
        if (typeof d === "object" && d !== null) {
            let title = d.title || "Discount";
            let amt = Number(d.price || discountsTotal || 0).toFixed(2);
            return `${title} (-$${amt})`;
        }
        let str = String(d).trim();
        if (/^\d+(\.\d+)?\)$/.test(str)) {
            return `Discount (-$${str}`;
        }
        if (str.endsWith("-") && Number(discountsTotal) > 0) {
            return `${str} (-$${Number(discountsTotal).toFixed(2)})`;
        }
        return str;
    });
}

function applyServiceAddressScheduleTimes(item) {
    let jobTimezone = resolveServiceTimezone(item.state, item.zip);

    if (item.correctionDate) {
        item.correctionDate = normalizeCalendarDateToNoonUTC(item.correctionDate, jobTimezone);
    }
    if (item.correctionTimeToken || item.correctionTime) {
        item.correctionTimeToken = normalizeTimeToken(item.correctionTimeToken, item.correctionTime);
    }

    if (!item.serviceDate) return;

    item.serviceDate = normalizeCalendarDateToNoonUTC(item.serviceDate, jobTimezone);
    if (item.originalScheduledDate) {
        item.originalScheduledDate = normalizeCalendarDateToNoonUTC(item.originalScheduledDate, jobTimezone);
    }

    item.timeToken = normalizeTimeToken(item.timeToken, item.scheduledTime);

    let arrivalHour = 9;
    let expectedHour = 11;
    if (item.timeToken === "token_2") {
        arrivalHour = 13;
        expectedHour = 15;
    } else if (item.timeToken === "token_3") {
        arrivalHour = 16;
        expectedHour = 18;
    }

    item.scheduledStartTime = buildLocalServiceTimestamp(item.serviceDate, arrivalHour, jobTimezone);
    item.deadlineTime = buildLocalServiceTimestamp(item.serviceDate, expectedHour, jobTimezone);
}

