                customer: `${j.firstName || ''} ${j.lastName || ''}`.trim(),
                totalPrice: j.totalPrice,
                detailer: j.detailerName,
                status: j.status
            }))
        };
    } catch (err) {
        return { errorLoadingCmsDigest: err.message };
    }
}

