                    }

                    $item("#jobsSelectDetailerMenuButton").onClick(async () => {
                        activeDetailerId = itemData._id;
                        
                        // 💥 NEW: This updates the Home Address for the ETA calculator!
                        activeContractorData = itemData; 
                        
                        if ($w("#jobsSelectDetailerButton").id) {
