export function initPaymentPortalEngine(wixContext, providedHooks) {
    logger.info("Initializing Payment Portal Engine...");
    $w = wixContext;
    hooks = providedHooks || {};

    // 1. Instantly attach UI click events (Does not block rendering)
    initPaymentUI($w);
