    error: (msg, data) => { data !== undefined ? console.error(`📌 [FILE_SITE_MENU]: ${msg}`, data) : console.error(`📌 [FILE_SITE_MENU]: ${msg}`); }
};

registerModuleState("fileSiteMenu", () => ({
    isLoggedInContractor,
