let cmsPackageData = [];
let userVehiclesList = [];

let selectedLevel = 'Classic';
let selectedType = 'Full';
let selectedServiceCategory = 'Auto';
let selectedVehicleSize = 'Car';
let selectedAddOns = [];
let activeSelectedVehicleObj = null;

