  try {
    const existingSlugs = Object.values(window._vaultSuggestionsById || {}).map(x => x.slug).join(", ");
    const askRes = await fetch(BASE_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-bridge-key": key },
