          whyItMattersForEcmd: item.whyItMattersForEcmd,
          externalDownloadsAndAccounts: item.externalDownloadsAndAccounts || ["Zero outside downloads"],
          implementationStepsPrompt: item.implementationStepsPrompt || item.summary,
          sourceConversationTopic: "Discover More from " + s.slug
        })
      });
    }
    await loadSuggestionsVault();
    setStatus("🔭 Added " + items.length + " new related suggestion(s) to your Vault!");
    setChatBox(
      "🔭 DISCOVERED & SAVED 2 NEW UPGRADES TO YOUR VAULT:\n\n" +
      items.map((i, idx) => (idx + 1) + ". " + i.title + "\n   • What it does: " + i.summary + "\n   • Why it helps ECMD: " + i.whyItMattersForEcmd).join("\n\n") +
      "\n\n💡 SUGGESTED NEXT STEP:\nScroll to the top of the Suggestions Vault below—you can mark either of these as 🔥 High Value or click ⚡ Start Build!"
    );
  } catch (e) {
    setStatus("Discover More Error: " + e.message, true);
    setChatBox("⚠️ I couldn't parse the newly discovered suggestions automatically: " + e.message, true);
  }
}

async function startSuggestionBuild(id) {
  const s = (window._vaultSuggestionsById || {})[id];
  if (!s) return;
  const key = getBridgeKey();
  setStatus("Starting Build for: " + s.title + "...");
  setChatBox(
    "⚡ STARTING AUTONOMOUS BUILD:\n" +
    "• Feature: " + s.title + "\n" +
    "• Action Taken: I marked this item as 'In Progress' and sent the build instructions to your local PowerShell Gemini CLI worker.\n" +
    "• What Happens Next: Your 3-Agent Velo Gatekeeper will verify the syntax as soon as it finishes, mark the suggestion 'Implemented' automatically, and I will summarize the finished build right here in plain English! (Raw technical logs are streaming in the File Inspector at the bottom.)"
  );
  const buildPrompt = `Build Suggestion [${s.slug}] (${s.title}): ${s.implementation_steps_prompt || s.summary}. When finished, update public.ecmd_advanced_suggestions status to 'implemented' for slug '${s.slug}' and log the learned capability into public.ecmd_external_ai_cms. End your response with a clear Plain-English summary of what you built and 1 suggested next step.`;
  try {
    await navigator.clipboard.writeText(`Start building suggestion '${s.slug}' (${s.title}): ${s.implementation_steps_prompt || s.summary}`);
  } catch (e) {}
  await fetch(BASE_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json", "x-bridge-key": key },
    body: JSON.stringify({ action: "update_suggestion_status", id: s.id, status: "in_progress" })
  });
  const safeP = buildPrompt.replace(/'/g, "''");
  await fetch(BASE_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json", "x-bridge-key": key },
    body: JSON.stringify({ action: "run_sql", sql: `INSERT INTO public.ecmd_cli_queue (prompt, status, source_agent) VALUES ('${safeP}', 'pending', 'VAULT_BUILD_BUTTON')` })
  });
  await loadCliQueuePanel(false);
}

function copySuggestionForSidePanel(id) {
  const s = (window._vaultSuggestionsById || {})[id];
  if (!s) return;
  navigator.clipboard.writeText(`Start building suggestion '${s.slug}' (${s.title}): ${s.implementation_steps_prompt || s.summary}`);
  setStatus("📋 Copied build prompt to clipboard!");
