}

async function updateSuggestionStatus(id, status) {
  const s = (window._vaultSuggestionsById || {})[id];
  const key = getBridgeKey();
  setStatus("Updating suggestion status to '" + status + "'...");
  await fetch(BASE_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json", "x-bridge-key": key },
    body: JSON.stringify({ action: "update_suggestion_status", id, status })
  });
  await loadSuggestionsVault();
  if (s) {
    const friendly = status === "high_value"
      ? "🔥 Pinned \"" + s.title + "\" to the very top of your Vault as a High Value Priority!"
      : (status === "unwanted"
        ? "💤 Marked \"" + s.title + "\" as Currently Unwanted and moved it to the bottom of your list."
        : "✅ Updated \"" + s.title + "\" status to '" + status + "'.");
    setChatBox(friendly);
  }
}

async function loadCliQueuePanel(isSilentPoll = false) {
  const key = getBridgeKey();
  if (!isSilentPoll) setStatus("Loading Local Gemini CLI Queue (public.ecmd_cli_queue)...");
  try {
    const existingInput = document.getElementById("cliPromptInput");
    const draftValue = existingInput ? existingInput.value : "";

    const res = await fetch(BASE_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-bridge-key": key },
      body: JSON.stringify({ action: "run_sql", sql: "SELECT id, prompt, status, output, source_agent, created_at, completed_at FROM public.ecmd_cli_queue ORDER BY created_at DESC LIMIT 15" })
    });
    const data = await res.json();
    const panel = document.getElementById("dynamicPanel");
    const title = document.getElementById("dynamicPanelTitle");
    const content = document.getElementById("dynamicPanelContent");
    panel.style.display = "block";

    const rows = data.rows || [];
    const hasActiveJob = rows.some(j => j.status === "pending" || j.status === "running");
    title.textContent = "🤖 Local Gemini CLI Dispatcher Queue " + (hasActiveJob ? "🟢 [AUTO-POLLING EVERY 4s...]" : "(Watched by Start-EcmdCliBridge.ps1 in C:\\ECMD)");

    document.getElementById("viewer").textContent = rows.map(r =>
      `=== JOB ${r.id} [${(r.status || "").toUpperCase()} • ${r.source_agent || "CLI"}] ===\nPrompt: ${r.prompt}\nOutput:\n${r.output || "(Waiting / Running...)"}\n`
    ).join("\n----------------------------------------\n");

    if (rows.length > 0) {
      const latest = rows[0];
      if (latest.status === "pending" || latest.status === "running") {
        setChatBox(
          "⏳ LOCAL CLI TASK IN PROGRESS:\n" +
          "• What I'm Doing: Running your task (" + latest.prompt.slice(0, 120) + "...) on your local PC via Start-EcmdCliBridge.ps1.\n" +
          "• Live Progress: Auto-refreshing every 4 seconds. As soon as it finishes, I will summarize the result in plain English right here, and put the technical logs in the File Inspector box below."
        );
      } else if (latest.status === "completed" && lastSummarizedJobId !== latest.id) {
        lastSummarizedJobId = latest.id;
        const rawOut = String(latest.output || "");
        const headerLine = (rawOut.match(/^\[Completed in[^\]]+\]/) || ["Completed successfully"])[0];
        const cleanBody = rawOut
          .replace(/^\[Completed in[^\]]+\]\s*/m, "")
          .replace(/node\.exe\s*:\s*Warning:[\s\S]*?CategoryInfo[^\n]+\n?/gi, "")
          .replace(/FullyQualifiedErrorId[^\n]+\n?/gi, "")
          .replace(/Loaded cached credentials\.\s*/gi, "")
          .trim();
        setChatBox(
          "✅ LOCAL CLI TASK COMPLETED " + headerLine + ":\n\n" +
          "📋 PLAIN-ENGLISH SUMMARY:\n" +
          (cleanBody || "The command finished executing with no output errors.") + "\n\n" +
          "💡 TIP:\nFull raw technical logs and JSON details are available in the File Inspector box at the bottom of the screen."
        );
      }
    }

    const jobsHtml = rows.map(j => `
      <div class="card">
        <div>
          <span class="badge" style="color:${j.status === 'completed' ? '#34d399' : '#fbbf24'};">${escapeHtml((j.status || '').toUpperCase())}</span>
          <span class="badge">${escapeHtml(j.source_agent || 'CLI')}</span>
          <strong>${escapeHtml(j.prompt.slice(0, 140))}${j.prompt.length > 140 ? '...' : ''}</strong>
        </div>
        <div style="color:#94a3b8;margin-top:4px;font-size:11.5px;">
          ${j.status === 'completed'
            ? '✅ Finished — Plain-English summary shown above; raw logs in File Inspector below.'
            : '⏳ Executing in C:\\ECMD via Start-EcmdCliBridge.ps1 (Auto-refreshing every 4s)...'}
        </div>
      </div>
    `).join("");

    if (!existingInput) {
      content.innerHTML = `
        <div class="row">
          <textarea id="cliPromptInput" class="auto-grow" rows="1" style="flex:1;min-width:220px;" oninput="autoResizeInput(this, 180)" onkeydown="if(event.key==='Enter' && !event.shiftKey){ event.preventDefault(); enqueueCliPrompt(); }" placeholder="Tip: Prefix with 'PS:' for <0.5s PowerShell, or type any AI task for Gemini CLI (auto-expands as you type)..."></textarea>
          <button class="warn" onclick="enqueueCliPrompt()">⚡ Send to PC PowerShell CLI</button>
          <button class="primary" onclick="loadCliQueuePanel(false)">🔄 Refresh</button>
        </div>
        <div id="cliJobsContainer" style="margin-top:8px;">${jobsHtml || "<div style='color:#94a3b8;margin-top:6px;'>No queued jobs yet.</div>"}</div>
      `;
    } else {
      const jobsContainer = document.getElementById("cliJobsContainer");
      if (jobsContainer) {
        jobsContainer.innerHTML = jobsHtml || "<div style='color:#94a3b8;margin-top:6px;'>No queued jobs yet.</div>";
      } else {
        content.innerHTML = `
          <div class="row">
            <textarea id="cliPromptInput" class="auto-grow" rows="1" style="flex:1;min-width:220px;" oninput="autoResizeInput(this, 180)" onkeydown="if(event.key==='Enter' && !event.shiftKey){ event.preventDefault(); enqueueCliPrompt(); }" placeholder="Tip: Prefix with 'PS:' for <0.5s PowerShell, or type any AI task for Gemini CLI (auto-expands as you type)..."></textarea>
            <button class="warn" onclick="enqueueCliPrompt()">⚡ Send to PC PowerShell CLI</button>
            <button class="primary" onclick="loadCliQueuePanel(false)">🔄 Refresh</button>
          </div>
          <div id="cliJobsContainer" style="margin-top:8px;">${jobsHtml}</div>
        `;
        const restored = document.getElementById("cliPromptInput");
        restored.value = draftValue;
        autoResizeInput(restored, 180);
      }
    }

    stopCliPoll();
    if (!hasActiveJob && window._pendingPostBuildSweep) {
      window._pendingPostBuildSweep = false;
      runFullSiteVeloDiagnosticSweep();
    }
    if (hasActiveJob) {
      window._pendingPostBuildSweep = true;
      cliAutoPollTimer = setTimeout(() => loadCliQueuePanel(true), 4000);
    }

    setStatus(hasActiveJob ? "⏳ Active CLI Job Running — Auto-Polling Every 4s..." : "Loaded " + rows.length + " Local Gemini CLI Queue job(s).");
  } catch (e) {
    setStatus("CLI Queue Error: " + e.message, true);
  }
}

async function enqueueCliPrompt() {
  const key = getBridgeKey();
  const el = document.getElementById("cliPromptInput");
  const p = el ? el.value.trim() : "";
  if (!p) return;
  setStatus("Sending prompt to your local PowerShell Gemini CLI...");
  setChatBox("⏳ I just sent your task (\"" + p + "\") to your local PowerShell worker. Watching for completion every 4 seconds...");
  const safeP = p.replace(/'/g, "''");
  await fetch(BASE_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json", "x-bridge-key": key },
    body: JSON.stringify({ action: "run_sql", sql: `INSERT INTO public.ecmd_cli_queue (prompt, status, source_agent) VALUES ('${safeP}', 'pending', 'CONSOLE_UI')` })
  });
  el.value = "";
  autoResizeInput(el, 180);
  await loadCliQueuePanel(false);
}

async function loadAiInbox() {
  stopCliPoll();
  const key = getBridgeKey();
  setStatus("Loading pending AI Unsure Questions & Recent Conversations...");
  try {
    const res = await fetch(BASE_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-bridge-key": key },
      body: JSON.stringify({ action: "get_ai_inbox" })
    });
    const data = await res.json();
    const panel = document.getElementById("dynamicPanel");
    const title = document.getElementById("dynamicPanelTitle");
    const list = document.getElementById("dynamicPanelContent");
    panel.style.display = "block";
    title.textContent = "📬 Pending Customer Questions (Flip Yes/No or Type Answer to Teach ECMD Brain)";
    const pending = (data.inbox || []).filter(i => i.status === "pending");

    setChatBox(
      "📬 AI UNSURE INBOX SUMMARY:\n" +
      (pending.length === 0
        ? "• You have 0 pending customer questions! Your ECMD Brain is completely caught up."
        : "• You have " + pending.length + " customer question(s) waiting for your Yes/No decision below. Clicking YES or NO teaches the ECMD Vector Brain permanently.")
    );

    if (pending.length === 0) {
      list.innerHTML = "<div style='margin-top:8px;color:#94a3b8;'>No pending unsure questions!</div>";
    } else {
      list.innerHTML = pending.map(item => `
        <div class="card">
          <div><strong style="color:#fbbf24;">Customer (${escapeHtml(item.customer_name || 'Visitor')} ${escapeHtml(item.customer_phone || '')}):</strong> "${escapeHtml(item.customer_question)}"</div>
          <div style="color:#94a3b8;margin-top:4px;"><em>AI Supplemental Reply Sent:</em> ${escapeHtml(item.ai_supplemental_reply_sent)}</div>
          <div style="color:#38bdf8;margin-top:6px;"><strong>AI Proposed Yes/No Question:</strong> ${escapeHtml(item.ai_yes_no_prompt_for_owner)}</div>
          <input id="ans_${item.id}" placeholder="Optional extra details or pricing rule..." />
          <div class="row">
            <button class="warn" onclick="answerInbox('${item.id}', true)">✅ YES (Teach Brain)</button>
            <button style="background:#dc2626;border-color:#f87171;font-weight:bold;" onclick="answerInbox('${item.id}', false)">❌ NO (Teach Brain)</button>
            <button class="primary" onclick="answerInbox('${item.id}', null)">💬 Save Text Answer Only</button>
          </div>
        </div>
      `).join("");
    }
    setStatus("Loaded " + pending.length + " pending AI Inbox item(s).");
    document.getElementById("viewer").textContent = JSON.stringify(data, null, 2);
  } catch (e) {
    setStatus("Inbox Error: " + e.message, true);
  }
}

async function answerInbox(inboxId, yesNoVal) {
  const key = getBridgeKey();
  const noteEl = document.getElementById("ans_" + inboxId);
  const noteText = noteEl ? noteEl.value : "";
  setStatus("Teaching ECMD Brain & marking question learned...");
  try {
    const res = await fetch(BASE_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-bridge-key": key },
      body: JSON.stringify({
        action: "answer_inbox_question",
        inboxId,
        ownerYesNoToggle: yesNoVal,
        ownerAnswerText: noteText
      })
    });
    const data = await res.json();
    setStatus("Learned! Brain Vector ID: " + data.learnedBrainId);
    setChatBox("✅ I saved your answer to the ECMD Vector Brain (ID: " + data.learnedBrainId + ") so customer chat will know this rule automatically going forward!");
    await loadAiInbox();
  } catch (e) {
    setStatus("Answer Error: " + e.message, true);
  }
}

