async function listCodebase() {
  stopCliPoll();
  const key = getBridgeKey();
  setStatus("Querying public.ecmd_codebase via Autonomous SQL...");
  try {
    const res = await fetch(BASE_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-bridge-key": key },
