async function readFile(path) {
  if (!path) return;
  const key = getBridgeKey();
  document.getElementById("customPath").value = path;
  document.getElementById("cloudFileTarget").value = path;
  setStatus("Reading " + path + " ...");
  try {
    const res = await fetch(BASE_URL + "?key=" + encodeURIComponent(key) + "&action=read_file&lines=1&path=" + encodeURIComponent(path));
    const data = await res.json();
    if (!data.ok) {
      setStatus("Error: " + (data.error || "Failed"), true);
      document.getElementById("viewer").textContent = JSON.stringify(data, null, 2);
      return;
    }
    if (data.files) {
      setStatus("Directory listing: " + path + " (" + data.files.length + " items)");
      setChatBox("📂 Loaded directory listing for " + path + " (" + data.files.length + " items) into the File Inspector box below.");
      document.getElementById("viewer").textContent = JSON.stringify(data.files, null, 2);
      return;
    }
    setStatus("LOADED (" + (data.source || "cache") + "): " + data.path + " | SHA: " + data.sha + " | Lines: " + data.lineCount);
    setChatBox(
      "📄 FILE LOADED INTO INSPECTOR: " + data.path + "\n" +
      "• Size: " + data.lineCount + " lines (loaded in <10ms from " + (data.source || "Supabase cache") + ").\n" +
      "• Full numbered source code is now visible in the File Inspector box at the bottom of the screen.\n" +
      "• Tip: Type a question or edit instruction in the auto-expanding box above and click '💬 Ask Carbon 4' or '🚀 Have Carbon 4 Edit File & Publish to Wix'!"
    );
    document.getElementById("viewer").textContent = "=== FILE: " + data.path + " (SHA: " + data.sha + " • Source: " + (data.source || "supabase") + ") ===\n" + (data.numberedContent || data.content);
  } catch (e) {
    setStatus("Fetch Error: " + e.message, true);
  }
}

async function publishNow() {
  const key = getBridgeKey();
  setStatus("Triggering Wix Publish...");
  setChatBox("⏳ Triggering a live Wix site publish on ecmdutah.com...");
  try {
    const res = await fetch(BASE_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-bridge-key": key },
      body: JSON.stringify({ action: "carbon_batch", publish: true, ops: [] })
    });
    const data = await res.json();
    setStatus("Wix Publish Status: " + data.wixPublishStatus);
    setChatBox("🚀 Wix Publish Complete! Status: " + data.wixPublishStatus + ". Your latest GitHub commits are now live on ecmdutah.com.");
    document.getElementById("viewer").textContent = JSON.stringify(data, null, 2);
  } catch (e) {
    setStatus("Publish Error: " + e.message, true);
  }
}

async function runBatch() {
  const key = getBridgeKey();
  const raw = document.getElementById("batchInput").value.trim();
  if (!raw) return;
  setStatus("Executing Carbon 4 Command Packet...");
  try {
    const payload = JSON.parse(raw);
    if (!payload.action) payload.action = "carbon_batch";
    const res = await fetch(BASE_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-bridge-key": key },
      body: JSON.stringify(payload)
    });
    const data = await res.json();
    setStatus("Packet Complete — ok: " + data.ok);
    setChatBox("⚡ Executed '" + payload.action + "' packet successfully (ok: " + data.ok + "). Full raw data output is displayed in the File Inspector below.");
    if (data.results && data.results.length === 1 && data.results[0].numberedContent) {
      const r = data.results[0];
      document.getElementById("viewer").textContent = "=== FILE: " + r.path + " (SHA: " + r.sha + ") ===\n" + r.numberedContent;
    } else {
      document.getElementById("viewer").textContent = JSON.stringify(data, null, 2);
    }
  } catch (e) {
    setStatus("JSON / Execution Error: " + e.message, true);
  }
}
